$pdo = db();
$exists = $pdo->prepare("SELECT id FROM social_posts WHERE canal='threads' AND agendado_para=? AND legenda=? LIMIT 1");
$ins = $pdo->prepare("INSERT INTO social_posts (canal,tipo,midia_tipo,legenda,imagem_url,carousel_urls,agendado_para,status) VALUES ('threads',?,?,?,?,?,?,'pendente')");
$out = [];
foreach ($posts as $p) {
    if ($p['url'] !== '') {
        $h = @get_headers($p['url'], true);
        if (!is_array($h) || !str_contains((string)($h[0] ?? ''), '200')) { $out[] = "MIDIA|ERRO|{$p['when']}|" . basename($p['url']); continue; }
    }
    $exists->execute([$p['when'], $p['text']]);
    if ($exists->fetchColumn()) { $out[] = "IGNORADO|{$p['when']}"; continue; }
    $ins->execute([$p['tipo'], $p['midia'], $p['text'], $p['url'], $p['carousel'] ? json_encode($p['carousel'], JSON_UNESCAPED_SLASHES) : null, $p['when']]);
    $out[] = "OK|id={$pdo->lastInsertId()}|{$p['when']}|{$p['tipo']}";
